package pe.edu.cacaoselva.monitor.scheduler;
import pe.edu.cacaoselva.application.port.LoteQueryPort; import java.time.Duration; import java.util.concurrent.*;
public class MonitorScheduler { private static final Duration INTERVALO_MONITOREO=Duration.ofSeconds(10); private final LoteQueryPort queryPort; private final ScheduledExecutorService scheduler=Executors.newSingleThreadScheduledExecutor(); public MonitorScheduler(LoteQueryPort queryPort){this.queryPort=queryPort;} public void iniciar(){scheduler.scheduleWithFixedDelay(this::ejecutarMonitoreo,0,INTERVALO_MONITOREO.toSeconds(),TimeUnit.SECONDS);} private void ejecutarMonitoreo(){try{var lotes=queryPort.obtenerLotes(); long pendientes=lotes.stream().filter(lote->"PENDIENTE".equals(lote.estado().name())).count(); System.out.println("Pendientes: "+pendientes);}catch(Exception ex){System.out.println("API no disponible: "+ex.getMessage());}} public void detener(){scheduler.shutdownNow();System.out.println("Monitor detenido correctamente.");} }
